from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_items(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header():
    # This should fail if convert_underscores=True (default)
    # But currently it might pass if we send 'my_header'
    response = client.get("/", headers={"my_header": "value"})
    print(f"Response with my_header: {response.json()}")
    assert response.status_code == 422, "Should not accept underscore headers by default"

def test_hyphen_header():
    # This should pass
    response = client.get("/", headers={"my-header": "value"})
    print(f"Response with my-header: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"my_header": "value"}

if __name__ == "__main__":
    try:
        test_underscore_header()
        print("test_underscore_header passed (but it should have failed!)")
    except AssertionError as e:
        print(f"test_underscore_header failed as expected: {e}")
    except Exception as e:
        print(f"test_underscore_header raised exception: {e}")

    try:
        test_hyphen_header()
        print("test_hyphen_header passed")
    except Exception as e:
        print(f"test_hyphen_header failed: {e}")
